files.content:
:root {
  --bg: #1a1c2c;
  --card: #2e2b44;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #e6a800;
  --border: #5a5a7a;
  --focus: #ffcd75;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--accent-dark);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  image-rendering: pixelated;
}

h1 {
  font-size: 28px;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--accent-dark);
}

.field {
  margin-bottom: 20px;
}

label, .label {
  display: block;
  margin-bottom: 8px;
  font-size: 16px;
  color: var(--text);
  letter-spacing: 1px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 18px;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  outline: none;
  transition: border-color 0.1s;
}

input[type="number"]:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px var(--focus);
}

input[type="number"]:hover {
  border-color: var(--accent);
}

.tip-buttons {
  display: flex;
  gap: 12px;
}

.tip-btn {
  flex: 1;
  padding: 12px 8px;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  cursor: pointer;
  transition: all 0.1s;
  image-rendering: pixelated;
}

.tip-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent-dark);
  box-shadow: 3px 3px 0 var(--accent-dark);
}

.tip-btn[aria-pressed="true"]:hover {
  background: var(--accent-dark);
  color: var(--bg);
}

.results {
  margin-top: 24px;
  border-top: 3px dashed var(--border);
  padding-top: 16px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  font-size: 18px;
}

.result-row.total {
  font-size: 22px;
  font-weight: bold;
  color: var(--accent);
  border-top: 2px solid var(--border);
  margin-top: 8px;
  padding-top: 12px;
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  .tip-buttons {
    gap: 8px;
  }
  .tip-btn {
    padding: 10px 4px;
    font-size: 16px;
  }
  h1 {
    font-size: 24px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tipPerPerson');
  const totalPerPersonEl = document.getElementById('totalPerPerson');

  let tipPercent = 0;

  function update() {
    const bill = parseFloat(billInput.value) || 0;
    const people = parseInt(peopleInput.value, 10) || 1;
    const tip = bill * (tipPercent / 100);
    const total = bill + tip;
    const tipPerPerson = tip / people;
    const totalPerPerson = total / people;
    tipPerPersonEl.textContent = '$' + tipPerPerson.toFixed(2);
    totalPerPersonEl.textContent = '$' + totalPerPerson.toFixed(2);
  }

  tipButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      tipPercent = parseFloat(btn.dataset.tip);
      tipButtons.forEach(b => b.setAttribute('aria-pressed', 'false'));
      btn.setAttribute('aria-pressed', 'true');
      update();
    });
  });

  billInput.addEventListener('input', update);
  peopleInput.addEventListener('input', update);

  update();
});
